-- Load errors left after D25 / D26 (D27). Generated by skyfire_port_plan/tools/dbcompare/d27_loaderrors_leftovers.py. Safe to run twice.

-- 1. The core reports only the first difficulty template whose NPC flags differ. D25 fixed difficulty 1;
--    these are the 10-man heroic / 25-man and Alterac Valley bracket templates of the same creatures.
UPDATE `creature_template` SET `npcflag` = 3 WHERE `entry` IN (31961,37279) AND `npcflag` = 2; -- Corporal Teeka Bloodsnarl (13776)
UPDATE `creature_template` SET `npcflag` = 130 WHERE `entry` IN (32003,37322) AND `npcflag` = 2; -- Herald (14848)
UPDATE `creature_template` SET `npcflag` = 16777216 WHERE `entry` IN (52560,52561) AND `npcflag` = 0; -- Lord Rhyolith (52558)
UPDATE `creature_template` SET `npcflag` = 16777216 WHERE `entry` IN (57938,57939) AND `npcflag` = 0; -- Goriona (56781)
-- ... and a difficulty template with the spell-click flag needs the spell click itself, or the core takes the flag away again
DELETE FROM `npc_spellclick_spells` WHERE (`npc_entry` IN (52559,52560,52561) AND `spell_id` = 98843) OR (`npc_entry` IN (57937,57938,57939) AND `spell_id` = 46598);

